CREATE OR REPLACE FUNCTION public.ring_post(_post_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.posts; caller uuid:=auth.uid(); previous text:=coalesce(current_setting('app.bell_notice',true),''); BEGIN IF caller IS NULL OR NOT public.account_allowed(caller) THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF; IF NOT public.has_paid_bell(caller) THEN RAISE EXCEPTION 'PAID_BELL_REQUIRED'; END IF; SELECT * INTO p FROM public.posts WHERE id=_post_id AND status='active' AND (visible_after IS NULL OR visible_after<=now()) AND (job_expires_at IS NULL OR job_expires_at>now()) AND public.account_allowed(user_id); IF p.id IS NULL OR p.user_id=caller THEN RAISE EXCEPTION 'POST_UNAVAILABLE'; END IF; UPDATE public.profiles SET bell_activated_at=coalesce(bell_activated_at,now()) WHERE id=caller; INSERT INTO public.post_chat_pairs(post_id,member_id,owner_id) VALUES(p.id,caller,p.user_id) ON CONFLICT DO NOTHING; PERFORM set_config('app.bell_notice','interest',true); PERFORM 1 FROM public.profiles WHERE id=p.user_id FOR UPDATE; INSERT INTO public.notifications(user_id,post_id,message) VALUES(p.user_id,p.id,'మీ ప్రకటన గంటను ఒకరు నొక్కారు; సంభాషణలో స్పందించండి.'); IF NOT EXISTS(SELECT 1 FROM public.messages WHERE post_id=p.id AND sender_id=caller AND receiver_id=p.user_id) THEN INSERT INTO public.messages(sender_id,receiver_id,post_id,body) VALUES(caller,p.user_id,p.id,'హాయ్ · Hi'); END IF; PERFORM set_config('app.bell_notice',previous,true); RETURN p.user_id; END $$;
CREATE OR REPLACE FUNCTION public.ring_service(_owner uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.account_allowed(auth.uid()) THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF; IF NOT public.has_paid_bell(auth.uid()) THEN RAISE EXCEPTION 'PAID_BELL_REQUIRED'; END IF; IF auth.uid()=_owner OR NOT public.account_allowed(_owner) OR NOT EXISTS(SELECT 1 FROM public.service_profiles WHERE user_id=_owner AND published) THEN RAISE EXCEPTION 'SERVICE_UNAVAILABLE'; END IF; INSERT INTO public.service_chat_pairs(member_id,owner_id) VALUES(auth.uid(),_owner) ON CONFLICT DO NOTHING; UPDATE public.profiles SET bell_activated_at=coalesce(bell_activated_at,now()) WHERE id=auth.uid(); PERFORM 1 FROM public.profiles WHERE id=_owner FOR UPDATE; INSERT INTO public.notifications(user_id,message) VALUES(_owner,'మీ సేవపై సమాచారం కోరారు; సంభాషణలో స్పందించండి.'); IF NOT EXISTS(SELECT 1 FROM public.messages WHERE sender_id=auth.uid() AND receiver_id=_owner AND post_id IS NULL) THEN INSERT INTO public.messages(sender_id,receiver_id,body) VALUES(auth.uid(),_owner,'హాయ్ · Hi'); END IF; RETURN _owner; END $$;